import os, sys, pty, time, select, fcntl, termios, struct, signal

def run(cmd, keys=b'', cols=80, rows=24, wait=0.4, env=None):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvpe(cmd[0], cmd, env if env else dict(os.environ))
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = b''
    time.sleep(wait)
    def drain():
        nonlocal out
        while True:
            r,_,_ = select.select([fd], [], [], 0.1)
            if not r: break
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out += d
    drain()
    for k in keys:
        os.write(fd, bytes([k]))
        time.sleep(0.15)
        drain()
    try:
        os.kill(pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        os.waitpid(pid, 0)
    except Exception:
        pass
    return out

if __name__ == '__main__':
    cmd = sys.argv[1].split()
    keys = sys.argv[2].encode().decode('unicode_escape').encode('latin1') if len(sys.argv)>2 else b''
    o = run(cmd, keys)
    sys.stdout.write(repr(o))
    sys.stdout.write('\n')
