{"command": "cat <<'EOF' > /tmp/tui.py
import os, sys, time, select, fcntl, termios, struct, signal, re

class Term:
    def __init__(self, cmd, cols=80, rows=24, cwd=None, env=None, bg='0000/0000/0000'):
        self.cols, self.rows = cols, rows
        r, w = os.openpty()
        self.master, self.slave = r, w
        fcntl.ioctl(w, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
        self.pid = os.fork()
        if self.pid == 0:
            os.setsid()
            os.dup2(w, 0); os.dup2(w, 1); os.dup2(w, 2)
            fcntl.ioctl(0, termios.TIOCSCTTY, 0)
            os.close(r); os.close(w)
            if cwd: os.chdir(cwd)
            e = dict(os.environ)
            e['TERM'] = 'xterm-256color'
            if env: e.update(env)
            os.execvpe(cmd[0], cmd, e)
            os._exit(1)
        os.close(w)
        self.bg = bg
        self.buf = []
        self.screen = [[' ']*cols for _ in range(rows)]
        self.attr = [['']*cols for _ in range(rows)]
        self.cx = self.cy = 0
        self.cur_attr = ''
        self.exited = False
        self.alive = True

    def send(self, data):
        if isinstance(data, str): data = data.encode()
        os.write(self.master, data)

    def _reply(self, chunk):
        s = chunk.decode('latin1')
        # OSC 11 background query
        out = b''
        i = 0
        while True:
            m = re.search(r'\x1b]11;\?(?:\x07|\x1b\\)', s[i:])
            if not m: break
            out += ('\x1b]11;rgb:%s\x1b\\' % self.bg).encode()
            i += m.end()
        if re.search(r'\x1b\[6n', s[i:]):
            out += ('\x1b[%d;%dR' % (self.cy+1, self.cx+1)).encode()
        if out: os.write(self.master, out)

    def feed(self):
        while True:
            r, _, _ = select.select([self.master], [], [], 0.05)
            if not r: return
            try:
                d = os.read(self.master, 65536)
            except OSError:
                self.alive = False; return
            if not d:
                self.alive = False; return
            self.buf.append(d)
            self._reply(d)
            self.parse(d)

    def parse(self, data):
        s = data.decode('utf-8', 'replace')
        i = 0
        while i < len(s):
            c = s[i]
            if c == '\x1b':
                m = re.match(r'\x1b\[([0-9;?]*)([A-Za-z])', s[i:])
                if m:
                    self.csi(m.group(1), m.group(2))
                    i += m.end(); continue
                m = re.match(r'\x1b\][^\x07\x1b]*(\x07|\x1b\\)', s[i:])
                if m:
                    i += m.end(); continue
                m = re.match(r'\x1b.', s[i:])
                if m:
                    i += m.end(); continue
                i += 1; continue
            if c == '\r': self.cx = 0; i+=1; continue
            if c == '\n':
                self.cy += 1
                if self.cy >= self.rows: self.cy = self.rows-1
                i+=1; continue
            if c == '\t': self.cx = (self.cx//8+1)*8; i+=1; continue
            if c == '\x08': self.cx = max(0, self.cx-1); i+=1; continue
            if ord(c) < 32: i+=1; continue
            if self.cy < self.rows and self.cx < self.cols:
                self.screen[self.cy][self.cx] = c
                self.attr[self.cy][self.cx] = self.cur_attr
            self.cx += 1
            if self.cx > self.cols: self.cx = self.cols
            i += 1

    def csi(self, params, final):
        ps = [p for p in params.split(';')]
        def n(k, d=1):
            try: v = int(ps[k]) if k < len(ps) and ps[k] else d
            except: v = d
            return v
        if final == 'H' or final == 'f':
            self.cy = min(self.rows-1, max(0, n(0,1)-1)); self.cx = min(self.cols-1, max(0, n(1,1)-1))
        elif final == 'A': self.cy = max(0, self.cy-n(0))
        elif final == 'B': self.cy = min(self.rows-1, self.cy+n(0))
        elif final == 'C': self.cx = min(self.cols-1, self.cx+n(0))
        elif final == 'D': self.cx = max(0, self.cx-n(0))
        elif final == 'J':
            v = n(0,0)
            if v == 2:
                self.screen = [[' ']*self.cols for _ in range(self.rows)]
                self.attr = [['']*self.cols for _ in range(self.rows)]
            elif v == 0:
                for x in range(self.cx, self.cols):
                    self.screen[self.cy][x]=' '; self.attr[self.cy][x]=''
                for y in range(self.cy+1, self.rows):
                    self.screen[y] = [' ']*self.cols; self.attr[y] = ['']*self.cols
        elif final == 'K':
            v = n(0,0)
            if v == 0:
                for x in range(self.cx, self.cols):
                    self.screen[self.cy][x]=' '; self.attr[self.cy][x]=''
            elif v == 1:
                for x in range(0, self.cx+1):
                    self.screen[self.cy][x]=' '; self.attr[self.cy][x]=''
            else:
                for x in range(self.cols):
                    self.screen[self.cy][x]=' '; self.attr[self.cy][x]=''
        elif final == 'm':
            if params == '' or params == '0':
                self.cur_attr = ''
            else:
                self.cur_attr = params
        elif final == 'S':
            v = n(0)
            for _ in range(v):
                self.screen.pop(0); self.screen.append([' ']*self.cols)
                self.attr.pop(0); self.attr.append(['']*self.cols)

    def text(self):
        return '\n'.join(''.join(r).rstrip() for r in self.screen)

    def lines(self):
        return [''.join(r).rstrip() for r in self.screen]

    def kill(self):
        try: os.kill(self.pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(self.pid, 0)
        except Exception: pass
        self.alive = False

def interact(cmd, script, cols=80, rows=24, cwd=None, env=None, verbose=False):
    """script: list of (seconds_to_wait, keys)"""
    t = Term(cmd, cols, rows, cwd, env)
    out = b''
    for delay, keys in script:
        for _ in range(int(delay/0.05)):
            t.feed()
            if not t.alive: break
        if keys:
            for ch in keys:
                t.send(ch if isinstance(ch,str) else bytes([ch]))
                time.sleep(0.03)
                t.feed()
    time.sleep(0.2)
    t.feed()
    return t

if __name__ == '__main__':
    pass
