                self.attr.pop(0); self.attr.append(['']*self.cols)

    def text(self):
        return '\n'.join(''.join(r).rstrip() for r in self.screen)

    def lines(self):
        return [''.join(r).rstrip() for r in self.screen]

    def kill(self):
        try: os.kill(self.pid, signal.SIGKILL)
        except Exception: pass
        try: os.waitpid(self.pid, 0)
        except Exception: pass
        self.alive = False

def interact(cmd, script, cols=80, rows=24, cwd=None, env=None, verbose=False):
    """script: list of (seconds_to_wait, keys)"""
    t = Term(cmd, cols, rows, cwd, env)
    out = b''
    for delay, keys in script:
        for _ in range(int(delay/0.05)):
