sys.path.insert(0,'/tmp')
from tui import interact
d='/tmp/g1'
if os.path.exists(d): shutil.rmtree(d)
os.makedirs(d)
for i in range(100):
    s=str(i); s='f'*(4-len(s))+s
    open(f'{d}/{s}','w').close()
def analyze(t):
    lines=[l for l in t.lines() if l.strip()]
    rows=len(lines)-1
    line=lines[1]
    pos=[m.start() for m in re.finditer(r'f+\d+', line)]
    stride = pos[1]-pos[0] if len(pos)>1 else None
    return rows, stride, len(pos), len(line)
for h in [16]:
    for w in [120,130,140,150,160,170,180,190,200,220,240,280,320,400]:
        t = interact(['/workspace/executable'], [(0.25,None)], w, h, d)
        print('h=%d w=%3d -> %s'%(h,w,analyze(t)))
EOF"}

